import { createServerClient } from '@supabase/ssr'
import { NextResponse } from 'next/server'
import { NextRequest } from 'next/server'

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const code = searchParams.get('code')

  // Get the actual origin from request headers (for proxy support)
  const forwardedHost = request.headers.get('x-forwarded-host');
  const forwardedProto = request.headers.get('x-forwarded-proto');
  const host = forwardedHost || request.headers.get('host') || 'localhost:9002';
  const protocol = forwardedProto || 'http';
  const origin = `${protocol}://${host}`;

  // OAuth リダイレクト先を複数ソースから取得（優先順位順）
  // 1. httpOnly Cookie（サーバー側で設定、最も安全）
  // 2. next query parameter（Supabase redirectTo 経由）
  // 3. クライアント側 Cookie（login ページで設定、フォールバック）
  // 4. デフォルト: /dashboard
  const oauthRedirectCookie = request.cookies.get('oauth_redirect')?.value;
  const oauthRedirectClient = request.cookies.get('oauth_redirect_client')?.value
    ? decodeURIComponent(request.cookies.get('oauth_redirect_client')!.value)
    : undefined;
  let nextParam = searchParams.get('next');

  // oauthRedirectCookie はパス（/oauth/authorize?...）で保存されている
  // 絶対URLの場合はパス+クエリのみ抽出（セキュリティ対策）
  let oauthRedirectPath: string | undefined;
  if (oauthRedirectCookie) {
    try {
      // 絶対URLかチェック
      const parsed = new URL(oauthRedirectCookie);
      oauthRedirectPath = `${parsed.pathname}${parsed.search}`;
    } catch {
      // 相対パスの場合はそのまま使用
      oauthRedirectPath = oauthRedirectCookie;
    }
  }

  // query parameterのnextが絶対URLの場合、パス+クエリのみ抽出
  if (nextParam) {
    try {
      const nextUrl = new URL(nextParam);
      nextParam = `${nextUrl.pathname}${nextUrl.search}`;
    } catch {
      // 相対パスの場合はそのまま
    }
  }

  // クライアント側 Cookie も同様にパス+クエリのみ抽出
  let clientRedirectPath: string | undefined;
  if (oauthRedirectClient) {
    try {
      const clientUrl = new URL(oauthRedirectClient);
      clientRedirectPath = `${clientUrl.pathname}${clientUrl.search}`;
    } catch {
      // 相対パスの場合はそのまま
      clientRedirectPath = oauthRedirectClient;
    }
  }

  const next = oauthRedirectPath || nextParam || clientRedirectPath || '/dashboard';
  // セキュリティ: 相対パスのみ許可（origin 付加で絶対URLにする）
  const redirectUrl = next.startsWith('/') ? `${origin}${next}` : `${origin}/dashboard`;

  console.log('[Auth Callback] Debug:', JSON.stringify({
    httpOnlyCookie: oauthRedirectCookie ? `found(${oauthRedirectCookie.substring(0, 50)}...)` : 'missing',
    clientCookie: oauthRedirectClient ? 'found' : 'missing',
    nextParam: nextParam ? `found(${nextParam.substring(0, 50)}...)` : 'missing',
    resolvedNext: next.substring(0, 80),
    code: code ? 'present' : 'missing',
    allCookieNames: request.cookies.getAll().map(c => c.name).join(','),
  }))

  if (code) {
    const pendingCookies: Array<{ name: string; value: string; options: Record<string, unknown> }> = [];

    const supabase = createServerClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
      {
        cookies: {
          getAll() {
            return request.cookies.getAll()
          },
          setAll(cookiesToSet) {
            pendingCookies.push(...cookiesToSet);
          },
        },
      }
    )

    const { data, error } = await supabase.auth.exchangeCodeForSession(code)

    console.log('[Auth Callback] Exchange:', {
      success: !error,
      error: error?.message,
      userId: data?.user?.id,
      pendingCookies: pendingCookies.length,
    })

    if (!error) {
      console.log('[Auth Callback] Redirecting to:', redirectUrl)
      const redirectResponse = NextResponse.redirect(redirectUrl, { status: 303 })
      redirectResponse.headers.set('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0')

      // Supabaseのセッションcookieをリダイレクトレスポンスに設定
      pendingCookies.forEach(({ name, value, options }) => {
        redirectResponse.cookies.set(name, value, options as any)
      })

      // oauth_redirect Cookieをクリア
      if (oauthRedirectCookie) {
        redirectResponse.cookies.delete('oauth_redirect');
      }
      if (oauthRedirectClient) {
        redirectResponse.cookies.delete('oauth_redirect_client');
      }
      return redirectResponse
    }

    console.error('[Auth Callback] Error:', error)
    return NextResponse.redirect(`${origin}/login?error=${encodeURIComponent(error.message)}`)
  }

  console.log('[Auth Callback] No code provided')
  return NextResponse.redirect(`${origin}/login?error=Could not authenticate user`)
}

/**
 * OAuth 2.0 Authorization Endpoint
 * GET /oauth/authorize
 * 
 * ユーザーに認可画面を表示し、同意を求める
 */

import { createClient } from '@/lib/supabase/server';
import { NextResponse } from 'next/server';
import { NextRequest } from 'next/server';
import { isValidRedirectUri, createOAuthError } from '@/lib/oauth';

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);

  // OAuth パラメータを取得
  const clientId = searchParams.get('client_id');
  const redirectUri = searchParams.get('redirect_uri');
  const state = searchParams.get('state');
  const codeChallenge = searchParams.get('code_challenge');
  const codeChallengeMethod = searchParams.get('code_challenge_method');
  const responseType = searchParams.get('response_type');
  const scope = searchParams.get('scope') || 'openid profile';

  // 必須パラメータのバリデーション
  if (!clientId || !redirectUri || !codeChallenge || !state) {
    return new Response(
      JSON.stringify(createOAuthError('invalid_request', 'Missing required parameters')),
      { status: 400, headers: { 'Content-Type': 'application/json' } }
    );
  }

  if (responseType !== 'code') {
    return new Response(
      JSON.stringify(createOAuthError('unsupported_response_type', 'Only "code" is supported')),
      { status: 400, headers: { 'Content-Type': 'application/json' } }
    );
  }

  if (codeChallengeMethod !== 'S256') {
    return new Response(
      JSON.stringify(createOAuthError('invalid_request', 'Only S256 code_challenge_method is supported')),
      { status: 400, headers: { 'Content-Type': 'application/json' } }
    );
  }

  const supabase = await createClient();

  // ユーザーのログイン状態を確認
  const { data: { user }, error: authError } = await supabase.auth.getUser();

  console.log('[OAuth Authorize] getUser:', {
    hasUser: !!user,
    userId: user?.id,
    error: authError?.message,
    cookieNames: request.cookies.getAll().map(c => c.name).join(','),
  });

  if (authError || !user) {
    // 未ログインの場合：ログイン画面へリダイレクト
    // リダイレクト先をパス+クエリで保存（内部URLの漏洩を防止）
    const requestUrl = new URL(request.url);
    const oauthPath = `${requestUrl.pathname}${requestUrl.search}`;

    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('redirect', request.url);
    const response = NextResponse.redirect(loginUrl, { status: 307 });
    // httpOnly Cookie にパスを保存（auth callback で読み取り）
    response.cookies.set('oauth_redirect', oauthPath, {
      httpOnly: true,
      secure: request.url.startsWith('https'),
      sameSite: 'lax',
      maxAge: 600,
      path: '/',
    });
    console.log('[OAuth Authorize] Redirecting to login, oauth_redirect cookie:', oauthPath.substring(0, 80));
    return response;
  }

  // クライアントアプリケーションを検証（RPC経由）
  const { data: applications, error: appError } = await supabase
    .rpc('get_application_by_client_id', { p_client_id: clientId });

  const application = applications?.[0];

  if (appError || !application) {
    return new Response(
      JSON.stringify(createOAuthError('invalid_client', 'Unknown client_id')),
      { status: 400, headers: { 'Content-Type': 'application/json' } }
    );
  }

  // リダイレクトURIを検証
  if (!isValidRedirectUri(redirectUri, application.redirect_uris)) {
    return new Response(
      JSON.stringify(createOAuthError('invalid_request', 'Invalid redirect_uri')),
      { status: 400, headers: { 'Content-Type': 'application/json' } }
    );
  }

  // 既に承認済みかチェック（RPC経由）
  const { data: hasConsent } = await supabase
    .rpc('check_user_consent', { p_user_id: user.id, p_application_id: application.id });

  const existingConsent = hasConsent;

  // 承認画面にパラメータを渡す
  const consentUrl = new URL('/oauth/authorize/consent', request.url);
  consentUrl.searchParams.set('client_id', clientId);
  consentUrl.searchParams.set('redirect_uri', redirectUri);
  consentUrl.searchParams.set('state', state);
  consentUrl.searchParams.set('code_challenge', codeChallenge);
  consentUrl.searchParams.set('code_challenge_method', codeChallengeMethod);
  consentUrl.searchParams.set('scope', scope);
  consentUrl.searchParams.set('app_name', application.name);

  if (existingConsent) {
    consentUrl.searchParams.set('already_consented', 'true');
  }

  return NextResponse.redirect(consentUrl, { status: 307 });
}

/**
 * OAuth 2.0 Token Endpoint
 * POST /oauth/token
 * 
 * 認可コードをアクセストークン（JWT）に交換
 */

import { createAdminClient } from '@/lib/supabase/server';
import {
  verifyClientSecret,
  verifyCodeChallenge,
  generateAccessToken,
  createOAuthError,
} from '@/lib/oauth';
import { NextResponse } from 'next/server';

export async function POST(request: Request) {
  const formData = await request.formData();

  const grantType = formData.get('grant_type') as string;
  const code = formData.get('code') as string;
  const redirectUri = formData.get('redirect_uri') as string;
  const clientId = formData.get('client_id') as string;
  const clientSecret = formData.get('client_secret') as string;
  const codeVerifier = formData.get('code_verifier') as string;

  // grant_type のバリデーション
  if (grantType !== 'authorization_code') {
    return NextResponse.json(
      createOAuthError('unsupported_grant_type'),
      { status: 400 }
    );
  }

  // 必須パラメータのチェック
  if (!code || !redirectUri || !clientId || !clientSecret || !codeVerifier) {
    return NextResponse.json(
      createOAuthError('invalid_request', 'Missing required parameters'),
      { status: 400 }
    );
  }

  // トークンエンドポイントはサーバー間通信（Cookie なし）なので
  // RLS をバイパスする Admin クライアントを使用
  const supabase = await createAdminClient();

  // クライアント認証（RPC経由）
  const { data: applications, error: appError } = await supabase
    .rpc('get_application_by_client_id', { p_client_id: clientId });

  const application = applications?.[0];

  if (appError || !application) {
    return NextResponse.json(
      createOAuthError('invalid_client'),
      { status: 401 }
    );
  }

  // クライアントシークレットの検証
  const isValidSecret = await verifyClientSecret(clientSecret, application.client_secret_hash);
  if (!isValidSecret) {
    return NextResponse.json(
      createOAuthError('invalid_client', 'Invalid client credentials'),
      { status: 401 }
    );
  }

  // 認可コードを取得（RPC経由）
  const { data: authCodes, error: codeError } = await supabase
    .rpc('get_authorization_code', { p_code: code });

  const authCode = authCodes?.[0];

  if (codeError || !authCode) {
    return NextResponse.json(
      createOAuthError('invalid_grant', 'Invalid or expired authorization code'),
      { status: 400 }
    );
  }

  // 認可コードの検証
  if (authCode.application_id !== application.id) {
    return NextResponse.json(
      createOAuthError('invalid_grant', 'Code was issued to different client'),
      { status: 400 }
    );
  }

  if (authCode.redirect_uri !== redirectUri) {
    return NextResponse.json(
      createOAuthError('invalid_grant', 'Redirect URI mismatch'),
      { status: 400 }
    );
  }

  // 有効期限チェック
  if (new Date(authCode.expires_at) < new Date()) {
    // 期限切れコードを削除（RPC経由）
    await supabase
      .rpc('delete_authorization_code', { p_code: code });

    return NextResponse.json(
      createOAuthError('invalid_grant', 'Authorization code expired'),
      { status: 400 }
    );
  }

  // PKCE 検証
  const isPKCEValid = verifyCodeChallenge(
    codeVerifier,
    authCode.code_challenge,
    authCode.code_challenge_method
  );

  if (!isPKCEValid) {
    return NextResponse.json(
      createOAuthError('invalid_grant', 'PKCE verification failed'),
      { status: 400 }
    );
  }

  // ユーザー情報を取得
  const { data: member } = await supabase
    .from('members')
    .select('*')
    .eq('supabase_auth_user_id', authCode.user_id)
    .single();

  if (!member) {
    return NextResponse.json(
      createOAuthError('server_error', 'User not found'),
      { status: 500 }
    );
  }

  // JWT アクセストークンを生成
  const accessToken = generateAccessToken(
    {
      sub: authCode.user_id,
      display_name: member.display_name,
      discord_id: member.discord_id,
      generation: member.generation,
      status: member.status,
      scope: authCode.scope,
    },
    clientId
  );

  // 使用済みコードを削除（RPC経由）
  await supabase
    .rpc('delete_authorization_code', { p_code: code });

  // トークンレスポンスを返す
  return NextResponse.json({
    access_token: accessToken,
    token_type: 'Bearer',
    expires_in: 3600, // 1時間
    scope: authCode.scope,
  });
}

/**
 * OAuth 2.0 UserInfo Endpoint
 * GET /oauth/userinfo
 * 
 * アクセストークンからユーザー情報を取得
 */

import { verifyAccessToken, createOAuthError } from '@/lib/oauth';
import { NextResponse } from 'next/server';

export async function GET(request: Request) {
  const authHeader = request.headers.get('Authorization');

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return NextResponse.json(
      createOAuthError('invalid_request', 'Missing or invalid Authorization header'),
      { status: 401 }
    );
  }

  const token = authHeader.substring(7); // "Bearer " を除去

  // JWT トークンを検証
  const payload = verifyAccessToken(token);

  if (!payload) {
    return NextResponse.json(
      createOAuthError('invalid_token', 'Invalid or expired access token'),
      { status: 401 }
    );
  }

  // ユーザー情報を返す
  return NextResponse.json({
    sub: payload.sub,
    display_name: payload.display_name,
    discord_id: payload.discord_id,
    generation: payload.generation,
    status: payload.status,
  });
}

/**
 * OAuth 2.0 ユーティリティ関数
 * JWT トークンの生成・検証、PKCE、ランダム文字列生成など
 */

import jwt from 'jsonwebtoken';
import crypto from 'crypto';
import bcrypt from 'bcryptjs';

// 環境変数から JWT シークレットキーを取得
const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key-change-in-production';
const JWT_ISSUER = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000';

// トークン有効期限
export const TOKEN_EXPIRY = {
  ACCESS_TOKEN: 60 * 60 * 24 * 30, // 30日（秒）
  AUTHORIZATION_CODE: 60 * 10, // 10分（秒）
};

/**
 * ランダムな文字列を生成（client_id, client_secret, codeなど）
 */
export function generateRandomString(length: number = 32): string {
  return crypto.randomBytes(length).toString('hex');
}

/**
 * Client Secret をハッシュ化
 */
export async function hashClientSecret(secret: string): Promise<string> {
  return bcrypt.hash(secret, 10);
}

/**
 * Client Secret を検証
 */
export async function verifyClientSecret(
  secret: string,
  hash: string
): Promise<boolean> {
  return bcrypt.compare(secret, hash);
}

/**
 * PKCE code_challenge を検証
 */
export function verifyCodeChallenge(
  verifier: string,
  challenge: string,
  method: string = 'S256'
): boolean {
  if (method !== 'S256') {
    return false;
  }

  const hash = crypto
    .createHash('sha256')
    .update(verifier)
    .digest('base64url');

  return hash === challenge;
}

/**
 * JWT アクセストークンを生成
 */
export interface JWTPayload {
  sub: string; // user_id
  display_name: string;
  discord_id: string;
  generation: number;
  status: number;
  scope: string;
}

export function generateAccessToken(
  payload: JWTPayload,
  clientId: string
): string {
  const now = Math.floor(Date.now() / 1000);

  return jwt.sign(
    {
      ...payload,
      iss: JWT_ISSUER,
      aud: clientId,
      iat: now,
      exp: now + TOKEN_EXPIRY.ACCESS_TOKEN,
    },
    JWT_SECRET,
    { algorithm: 'HS256' }
  );
}

/**
 * JWT アクセストークンを検証・デコード
 */
export function verifyAccessToken(token: string, clientId?: string): JWTPayload | null {
  try {
    const decoded = jwt.verify(token, JWT_SECRET, {
      algorithms: ['HS256'],
      issuer: JWT_ISSUER,
      audience: clientId,
    }) as JWTPayload & { iat: number; exp: number; iss: string; aud: string };

    return {
      sub: decoded.sub,
      display_name: decoded.display_name,
      discord_id: decoded.discord_id,
      generation: decoded.generation,
      status: decoded.status,
      scope: decoded.scope,
    };
  } catch (error) {
    console.error('Token verification failed:', error);
    return null;
  }
}

/**
 * Authorization Code の有効期限を計算
 */
export function getAuthCodeExpiry(): Date {
  return new Date(Date.now() + TOKEN_EXPIRY.AUTHORIZATION_CODE * 1000);
}

/**
 * リダイレクトURIが許可リストに含まれているか検証
 */
export function isValidRedirectUri(
  redirectUri: string,
  allowedUris: string[]
): boolean {
  return allowedUris.includes(redirectUri);
}

/**
 * OAuth エラーレスポンスを構築
 */
export interface OAuthError {
  error: string;
  error_description?: string;
}

export function createOAuthError(
  error: string,
  description?: string
): OAuthError {
  const result: OAuthError = { error };
  if (description) {
    result.error_description = description;
  }
  return result;
}

/**
 * エラーをリダイレクトURIに付加
 */
export function redirectWithError(
  redirectUri: string,
  error: OAuthError,
  state?: string
): string {
  const url = new URL(redirectUri);
  url.searchParams.set('error', error.error);
  if (error.error_description) {
    url.searchParams.set('error_description', error.error_description);
  }
  if (state) {
    url.searchParams.set('state', state);
  }
  return url.toString();
}

"use server";

import { createClient, createAdminClient } from '@/lib/supabase/server';
import { revalidatePath } from 'next/cache';
import { z } from 'zod';
import { ensureGenerationRoleExists } from './generations';

const studentNumberRegex = /^[0-9]+$/;

// Schema for re-syncing Discord member (for users who left and rejoined)
const reSyncSchema = z.object({
    last_name: z.string().min(1, '姓は必須です。'),
    first_name: z.string().min(1, '名は必須です。'),
});

// Schema for updating own profile (allows changing student number)
const profileUpdateSchema = z.object({
    student_number: z.string().regex(/^[0-9]*$/, '学籍番号は半角数字で入力してください。').optional().nullable(),
});


// Schema for admin updating profile
const profileAdminUpdateSchema = z.object({
    last_name: z.string().min(1, '姓は必須です。'),
    first_name: z.string().min(1, '名は必須です。'),
    generation: z.coerce.number().int().min(0, '期は0以上の数字である必要があります。'),
    student_number: z.string().optional().nullable(),
    status: z.coerce.number().int().min(0).max(2),
    team_ids: z.array(z.string()).optional(),
});

// Schema for initial registration
const registerSchema = z.object({
    last_name: z.string().min(1, '姓は必須です。'),
    first_name: z.string().min(1, '名は必須です。'),
    status: z.coerce.number().int().min(0).max(2),
    grade: z.coerce.number().int().min(1).max(3).optional(),
    student_number: z.string().regex(studentNumberRegex, '学籍番号は半角数字で入力してください。').optional().nullable(),
    generation: z.coerce.number().int().min(1, '期は正の整数である必要があります。').optional(),
    team_ids: z.array(z.string()).optional(),
}).refine(data => {
    if (data.status === 0 || data.status === 1) {
        return !!data.grade;
    }
    return true;
}, {
    message: '学年は必須です。',
    path: ['grade'],
}).refine(data => {
    if (data.status === 2) { // OB/OG
        return !!data.generation;
    }
    return true;
}, {
    message: '期は必須です。',
    path: ['generation'],
});

async function checkAdmin() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error('Authentication required.');

    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
    if (!admin?.is_admin) throw new Error('Administrator privileges required.');
}

function getAcademicYear() {
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth(); // 0-indexed (0 for January)
    return month >= 3 ? year : year - 1; // Academic year starts in April (month 3)
}

function calculateGeneration(status: number, grade: number, academicYear: number) {
    if (status === 1) { // High School
        return 10 + (academicYear - 2025) - grade + 1;
    }
    if (status === 0) { // Junior High
        return 10 + (academicYear - 2025) + 4 - grade;
    }
    return null;
}

