import { createServerClient, type CookieOptions } from '@supabase/ssr'
import { createClient as createSupabaseJsClient } from '@supabase/supabase-js'
import { cookies } from 'next/headers'

// DO NOT CHANGE THE SCHEMA NAME. IT IS 'member' AND SHOULD NOT BE MODIFIED.
// このスキーマ名は絶対に変更しないでください。'member' が正しい値です。
async function createSupabaseClient(isAdmin: boolean = false) {
  const cookieStore = await cookies()

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!
  const supabaseKey = isAdmin 
    ? process.env.SUPABASE_SERVICE_ROLE_KEY! 
    : process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!

  if (isAdmin && !process.env.SUPABASE_SERVICE_ROLE_KEY) {
    throw new Error('SUPABASE_SERVICE_ROLE_KEY is not defined in .env');
  }

  return createServerClient(supabaseUrl, supabaseKey, {
    db: {
        schema: 'member', // DO NOT CHANGE THIS VALUE.
    },
    auth: {
      autoRefreshToken: !isAdmin,
      persistSession: !isAdmin,
      // Only the middleware should auto-refresh the session.
      // Other server-side clients should not.
      detectSessionInUrl: false,
    },
    cookies: {
      getAll() {
        return cookieStore.getAll()
      },
      setAll(cookiesToSet) {
        try {
          cookiesToSet.forEach(({ name, value, options }) =>
            cookieStore.set(name, value, options)
          )
        } catch {
          // The `setAll` method was called from a Server Component.
          // This can be ignored if you have middleware refreshing
          // user sessions.
        }
      },
    },
  })
}

export async function createClient() {
  return await createSupabaseClient(false);
}

export async function createAdminClient() {
  // service_roleクライアントはcookieベースのSSRクライアントを使わない。
  // createServerClient (SSR) はcookieからユーザーJWTを読み込み、
  // Authorization headerを上書きするため、RLSがauthenticatedロールで評価され
  // UPDATE/DELETE等が静かに0行返る問題がある。
  // @supabase/supabase-jsのcreateClientを直接使用してRLSをバイパスする。
  if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
    throw new Error('SUPABASE_SERVICE_ROLE_KEY is not defined in .env');
  }
  return createSupabaseJsClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
    {
      db: {
        schema: 'member', // DO NOT CHANGE THIS VALUE.
      },
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }
  );
}

"use server";

import { createClient, createAdminClient } from '@/lib/supabase/server';
import { revalidatePath } from 'next/cache';
import { z } from 'zod';
import type { Team } from '../types';

const teamSchema = z.object({
  id: z.string().uuid().optional(),
  name: z.string().min(1, '班の名前は必須です。'),
  discord_role_id: z.string().min(1, 'DiscordロールIDは必須です。'),
});

async function checkAdmin() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error('認証が必要です。');

    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
    if (!admin?.is_admin) throw new Error('管理者権限が必要です。');
}

async function syncDiscordRoles(discordUid: string) {
    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
    const token = process.env.STEM_BOT_API_BEARER_TOKEN;

    console.log(`[Discord Bot] Attempting to sync roles for discord_uid: ${discordUid}`);

    if (!apiUrl || !token) {
        console.error('[Discord Bot] API URL or Bearer Token is not configured for Discord role sync.');
        return;
    }

    try {
        const res = await fetch(`${apiUrl}/api/roles/sync`, {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({ discord_uid: discordUid }),
            cache: 'no-store',
        });
         if (!res.ok) {
            const errorText = await res.text();
            console.error(`[Discord Bot] Failed to sync roles for ${discordUid}. Status: ${res.status}, Body: ${errorText}`);
        } else {
            console.log(`[Discord Bot] Successfully initiated role sync for discord_uid: ${discordUid}`);
        }
    } catch (e) {
        console.error(`[Discord Bot] Error during role sync for ${discordUid}:`, e);
    }
}


export async function createTeam(values: z.infer<typeof teamSchema>): Promise<{ error: string | null, team: Team | null }> {
    try {
        await checkAdmin();
        const supabaseAdmin = await createAdminClient();
        const parsedData = teamSchema.safeParse(values);
        if (!parsedData.success) return { error: '無効なデータです。', team: null };

        const { name, discord_role_id } = parsedData.data;

        const { data: newTeam, error } = await supabaseAdmin
            .from('teams')
            .insert({ name, discord_role_id })
            .select()
            .single();

        if (error) throw error;

        revalidatePath('/dashboard/admin/teams');
        return { error: null, team: newTeam };
    } catch (e: any) {
        return { error: e.message, team: null };
    }
}

export async function updateTeam(values: z.infer<typeof teamSchema>): Promise<{ error: string | null, team: Team | null }> {
    try {
        await checkAdmin();
        const supabaseAdmin = await createAdminClient();
        const parsedData = teamSchema.safeParse(values);
        if (!parsedData.success || !parsedData.data.id) return { error: '無効なデータです。', team: null };

        const { id, name, discord_role_id } = parsedData.data;
        const { data: updatedTeam, error } = await supabaseAdmin
            .from('teams')
            .update({ name, discord_role_id })
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;

        revalidatePath('/dashboard/admin/teams');
        return { error: null, team: updatedTeam };
    } catch (e: any) {
        return { error: e.message, team: null };
    }
}

export async function deleteTeam(teamId: string): Promise<{ error: string | null }> {
    try {
        await checkAdmin();
        const supabaseAdmin = await createAdminClient();

        const { error } = await supabaseAdmin.from('teams').delete().eq('id', teamId);
        if (error) throw error;

        revalidatePath('/dashboard/admin/teams');
        return { error: null };
    } catch (e: any) {
        return { error: e.message };
    }
}


export async function updateTeamLeaders(teamId: string, memberIds: string[]): Promise<{ error: string | null }> {
    try {
        await checkAdmin();
        const supabase = await createClient();
        const supabaseAdmin = await createAdminClient();

        // Find old leaders to sync their roles later
        const { data: oldLeadersData, error: oldLeadersError } = await supabaseAdmin.from('team_leaders')
            .select('member_id')
            .eq('team_id', teamId);

        if (oldLeadersError) throw oldLeadersError;

        const oldLeaderIds = oldLeadersData.map(l => l.member_id);

        const { error: deleteError } = await supabaseAdmin.from('team_leaders').delete().eq('team_id', teamId);
        if (deleteError) throw deleteError;

        if (memberIds.length > 0) {
            const newLeaders = memberIds.map(member_id => ({ team_id: teamId, member_id }));
            const { error: insertError } = await supabaseAdmin.from('team_leaders').insert(newLeaders);
            if (insertError) throw insertError;
        }

        const idsToSync = [...new Set([...oldLeaderIds, ...memberIds])];

        if (idsToSync.length > 0) {
            const { data: membersToSync, error: membersError } = await supabase.from('members')
                .select('discord_uid')
                .in('supabase_auth_user_id', idsToSync);

            if (membersError) throw membersError;

            if (membersToSync) {
                 console.log(`[Discord Bot] Syncing roles for ${membersToSync.length} members affected by leader change in team ${teamId}`);
                for (const member of membersToSync) {
                    await syncDiscordRoles(member.discord_uid);
                }
            }
        }

        revalidatePath('/dashboard/admin/teams');
        return { error: null };
    } catch (e: any) {
        console.error("Error updating team leaders:", e);
        return { error: e.message };
    }
}

"use server";

import { createClient, createAdminClient } from '@/lib/supabase/server';
import { revalidatePath } from 'next/cache';
import type { GenerationRole } from '../types';

async function checkAdmin() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error('Authentication required.');

    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
    if (!admin?.is_admin) throw new Error('Administrator privileges required.');
}

async function callCreateGenerationApi(generation: number): Promise<GenerationRole | null> {
    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
    const token = process.env.STEM_BOT_API_BEARER_TOKEN;

    if (!apiUrl || !token) {
        throw new Error('API URL or Bearer Token is not configured.');
    }

    const response = await fetch(`${apiUrl}/api/generation`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ generation }),
        cache: 'no-store',
    });

    const result = await response.json();

    if (!response.ok || !result.success) {
        throw new Error(result.error || 'Discordロールの作成に失敗しました。');
    }

    return {
        generation: result.generation,
        discord_role_id: result.role_id,
    };
}


export async function ensureGenerationRoleExists(generation: number): Promise<void> {
    const supabase = await createClient();
    const { data: existingRole } = await supabase
        .from('generation_roles')
        .select('generation')
        .eq('generation', generation)
        .single();

    if (!existingRole) {
        try {
            await callCreateGenerationApi(generation);
            // The API saves to the DB, but revalidation is good.
            revalidatePath('/dashboard/admin/generations');
        } catch (e: any) {
            // This might fail if another process created it in the meantime.
            // We can ignore the error for this "ensure" function.
             console.error(`Could not ensure generation role for ${generation} exists: ${e.message}`);
        }
    }
}


export async function createGenerationRole(generation: number): Promise<{ error: string | null, newRole: GenerationRole | null }> {
    try {
        await checkAdmin();
        const supabase = await createClient();

        // Check if role already exists in DB
        const { data: existingRole, error: existingError } = await supabase
            .from('generation_roles')
            .select('generation')
            .eq('generation', generation)
            .single();

        if (existingError && existingError.code !== 'PGRST116') { // PGRST116 is "No rows found"
            throw existingError;
        }
        if (existingRole) {
            return { error: `期生 ${generation} は既に存在します。`, newRole: null };
        }

        const newRole = await callCreateGenerationApi(generation);

        revalidatePath('/dashboard/admin/generations');
        return { error: null, newRole };

    } catch (e: any) {
        console.error('Error creating generation role:', e);
        return { error: e.message, newRole: null };
    }
}


export async function updateGenerationRoles(roles: GenerationRole[]): Promise<{ error: string | null }> {
    try {
        await checkAdmin();
        const supabaseAdmin = await createAdminClient();

        // Use a transaction to update all roles
        // First delete all existing roles, then insert the new ones.
        // This is simpler than upserting for this use case.

        const { error: deleteError } = await supabaseAdmin.from('generation_roles').delete().neq('generation', -1); // delete all
        if (deleteError) throw deleteError;

        // Filter out any rows that might be empty from the UI
        const validRoles = roles.filter(r => r.generation >= 0 && String(r.discord_role_id).trim() !== '');

        if (validRoles.length > 0) {
            const { error: insertError } = await supabaseAdmin.from('generation_roles').insert(validRoles);
            if (insertError) throw insertError;
        }

        revalidatePath('/dashboard/admin/generations');
        return { error: null };
    } catch (e: any) {
        return { error: e.message };
    }
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'

/**
 * セッションCookieをリダイレクトレスポンスにコピーする。
 * getUser() がトークンをリフレッシュした場合、新しいCookieをリダイレクトにも
 * 含めないと、ブラウザが古い（消費済みの）リフレッシュトークンで次のリクエストを
 * 送り、セッションが無効になる。
 */
function copySessionCookies(from: NextResponse, to: NextResponse) {
  from.cookies.getAll().forEach((cookie) => {
    to.cookies.set(cookie.name, cookie.value)
  })
}

export async function updateSession(request: NextRequest) {
  let supabaseResponse = NextResponse.next({
    request,
  })

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          // リクエストCookieにも書き込む（下流のRoute Handlerに伝播するため）
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value))
          supabaseResponse = NextResponse.next({
            request,
          })
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options)
          )
        },
      },
    }
  )

  const {
    data: { user },
  } = await supabase.auth.getUser()

  // 公開パス（認証不要）
  const isPublicPath = request.nextUrl.pathname.startsWith('/login')
    || request.nextUrl.pathname.startsWith('/auth/callback')
    || request.nextUrl.pathname.startsWith('/oauth')
    || request.nextUrl.pathname.startsWith('/api');

  // ログインしていないユーザーが保護されたページにアクセスした場合、ログインページにリダイレクト
  if (!user && !isPublicPath) {
    const loginRedirect = NextResponse.redirect(new URL('/login', request.url))
    copySessionCookies(supabaseResponse, loginRedirect)
    return loginRedirect
  }

  // ログインしているユーザーがログインページにアクセスした場合
  if (user && request.nextUrl.pathname.startsWith('/login')) {
    const redirectParam = request.nextUrl.searchParams.get('redirect');
    if (redirectParam) {
      // OAuth フローからのリダイレクト：同一オリジンの /oauth/ パスのみ許可
      try {
        const redirectUrl = new URL(redirectParam);
        const requestOrigin = new URL(request.url).origin;
        if (redirectUrl.origin === requestOrigin && redirectUrl.pathname.startsWith('/oauth/')) {
          const oauthRedirect = NextResponse.redirect(redirectUrl);
          copySessionCookies(supabaseResponse, oauthRedirect)
          return oauthRedirect;
        }
      } catch {
        // 不正なURLの場合はダッシュボードへ
      }
    }
    const dashRedirect = NextResponse.redirect(new URL('/dashboard', request.url))
    copySessionCookies(supabaseResponse, dashRedirect)
    return dashRedirect
  }

  return supabaseResponse
}

/**
 * OAuth クライアント管理 API
 * POST: 新規クライアント作成
 */

import { createClient } from '@/lib/supabase/server';
import { NextResponse } from 'next/server';
import { generateRandomString, hashClientSecret } from '@/lib/oauth';

export async function POST(request: Request) {
  const supabase = await createClient();

  // 管理者チェック
  const { data: { user } } = await supabase.auth.getUser();

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { data: member } = await supabase
    .from('members')
    .select('is_admin')
    .eq('supabase_auth_user_id', user.id)
    .single();

  if (!member?.is_admin) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  // リクエストボディを取得
  const body = await request.json();
  const { name, redirect_uris } = body;

  if (!name || !redirect_uris || !Array.isArray(redirect_uris) || redirect_uris.length === 0) {
    return NextResponse.json(
      { error: 'Invalid request: name and redirect_uris are required' },
      { status: 400 }
    );
  }

  // クライアントIDとシークレットを生成
  const clientId = generateRandomString(32);
  const clientSecret = generateRandomString(48);
  const clientSecretHash = await hashClientSecret(clientSecret);

  // RPC関数を使用してアプリケーションを作成
  const { data: application, error } = await supabase
    .rpc('create_application', {
      p_name: name,
      p_client_id: clientId,
      p_client_secret_hash: clientSecretHash,
      p_redirect_uris: redirect_uris,
      p_created_by: user.id,
    })
    .single();

  if (error) {
    console.error('Failed to create OAuth client:', error);
    return NextResponse.json(
      { error: 'Failed to create client' },
      { status: 500 }
    );
  }

  // クライアントシークレットは作成時のみ返す（平文）
  return NextResponse.json({
    ...application,
    client_secret: clientSecret, // 一度だけ表示
  });
}

/**
 * OAuth クライアント削除 API
 * DELETE: クライアント削除
 */

import { createClient } from '@/lib/supabase/server';
import { NextResponse } from 'next/server';

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const supabase = await createClient();

  // 管理者チェック
  const { data: { user } } = await supabase.auth.getUser();

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { data: member } = await supabase
    .from('members')
    .select('is_admin')
    .eq('supabase_auth_user_id', user.id)
    .single();

  if (!member?.is_admin) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  const { id } = await params;

  // RPC関数を使用してクライアントを削除
  const { data: deleted, error } = await supabase
    .rpc('delete_application', { p_id: id });

  if (error || !deleted) {
    console.error('Failed to delete OAuth client:', error);
    return NextResponse.json(
      { error: 'Failed to delete client' },
      { status: 500 }
    );
  }

  return NextResponse.json({ success: true });
}

/**
 * ユーザーの連携解除 API
 * DELETE: 連携を解除
 */

import { createClient } from '@/lib/supabase/server';
import { NextResponse } from 'next/server';

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { id } = await params;

  // 自分の承認記録のみ削除可能（RPC経由）
  const { data: deleted, error } = await supabase
    .rpc('delete_user_consent', { p_consent_id: id, p_user_id: user.id });

  if (error) {
    console.error('Failed to revoke consent:', error);
    return NextResponse.json(
      { error: 'Failed to revoke consent' },
      { status: 500 }
